// 语法汇总页的搜索：中文 / 拼音（声调可省）/ 英文，省略号当通配（越来越 → 越…越…）。
// The index (src/data/grammar/index.json, generated by convert_grammar.py) is a
// dynamic import so it stays out of the main bundle — only GrammarIndexView pulls it.

const strip = (s) => (s || "").normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase();
// Punctuation / quotes / ellipses / spaces don't matter when matching Chinese.
const norm = (s) => strip(s).replace(/[“”"'‘’「」『』（）()…\.\s·、，,：:；;？?！!。\/+＋～~]/g, "").replace(/ü/g, "v");

let _index = null;
export function loadGrammarIndex() {
  if (!_index) {
    _index = import("@/data/grammar/index.json").then((m) =>
      m.default.map((p, k) => {
        const name = norm(p.name);
        return {
          ...p,
          k, // stable row id
          _name: name,
          _core: norm([p.name, p.st, p.type].join("|")),
          _py: strip(p.py).replace(/[^a-z]/g, ""),
          _en: strip([p.en, p.stEn, p.typeEn].join(" ")),
          _eg: norm(p.eg),
          // 「越…越…」 → /越.{0,4}越/，让搜「越来越」也能命中
          _pat: /…|\.\.\./.test(p.name)
            ? new RegExp(
                p.name
                  .split(/…+|\.{3,}/)
                  .map(norm)
                  .filter(Boolean)
                  .map((x) => x.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"))
                  .join(".{0,4}")
              )
            : null,
        };
      })
    );
  }
  return _index;
}

export function matches(p, q, withExamples = false) {
  if (!q) return true;
  const n = norm(q);
  if (!n) return true;
  if (p._core.includes(n)) return true;
  if (p._pat && p._pat.test(n)) return true;
  const s = strip(q).trim();
  if (/^[a-z\s']+$/.test(s) && s.replace(/[\s']/g, "").length >= 2) {
    if (p._py.includes(s.replace(/[\s']/g, ""))) return true;
    if (s.length >= 3 && p._en.includes(s)) return true;
  }
  return withExamples && p._eg.includes(n);
}

// Lower = more relevant. Name starts with the term < name contains it < structure < anything else.
export function rank(p, q) {
  if (!q) return 0;
  const n = norm(q);
  if (p._name.startsWith(n) || p._name.replace(/^.?字句/, "").startsWith(n)) return 0;
  if (p._name.includes(n) || (p._pat && p._pat.test(n))) return 1;
  if (p._core.includes(n)) return 2;
  return 3;
}

const esc = (s) => String(s ?? "").replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c]);

// Escaped HTML with the query's pieces wrapped in <mark>. No query → just escaped text.
export function highlight(text, q) {
  const safe = esc(text);
  const parts = (q || "")
    .trim()
    .split(/[…\s]+|\.{3,}/)
    .filter((x) => x.length >= 2 || /[\u4e00-\u9fff]/.test(x)) // a lone latin letter would light up everything
    .map((x) => esc(x).replace(/[.*+?^${}()|[\]\\]/g, "\\$&"));
  if (!parts.length) return safe;
  return safe.replace(new RegExp(`(${parts.join("|")})`, "gi"), "<mark>$1</mark>");
}
